previewCss:
.darma-loader-horseshoe-magnet {
  position: relative;
  width: 44px;
  height: 48px;
}
.darma-loader-horseshoe-magnet::before {
  content: "";
  position: absolute;
  bottom: 4px;
  left: 50%;
  width: 30px;
  height: 30px;
  margin-left: -15px;
  border: 8px solid var(--loader-color, #6366f1);
  border-top: 0;
  border-radius: 0 0 16px 16px;
  box-sizing: border-box;
}
.darma-loader-horseshoe-magnet::after {
  content: "";
  position: absolute;
  top: 6px;
  left: 50%;
  margin-left: -15px;
  width: 8px;
  height: 6px;
  background: #4338ca;
  box-shadow: 22px 0 0 #4338ca;
  border-radius: 2px 2px 0 0;
}
.darma-loader-horseshoe-magnet i {
  position: absolute;
  top: 0;
  left: 50%;
  width: 26px;
  height: 12px;
  margin-left: -13px;
  border: 2px solid var(--loader-color, #6366f1);
  border-bottom: 0;
  border-radius: 16px 16px 0 0;
  box-sizing: border-box;
  transform-origin: bottom center;
  animation: darma-loader-horseshoe-magnet-field 1.2s ease-in-out infinite;
}
@keyframes darma-loader-horseshoe-magnet-field {
  0%, 100% { opacity: 0.2; transform: scale(0.8); }
  50% { opacity: 1; transform: scale(1.15); }
}

